import sys
from collections import defaultdict

def normalize_hostname(hostname):
    if hostname.endswith('/'):
        hostname = hostname[:-1]
    return hostname

def main():
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    hostnames = data[1:]

    normalized_hostnames = [normalize_hostname(hostname) for hostname in hostnames]

    hostname_groups = defaultdict(set)

    for hostname in normalized_hostnames:
        for other_hostname in normalized_hostnames:
            if hostname != other_hostname and hostname in other_hostname or other_hostname in hostname:
                hostname_groups[hostname].add(other_hostname)
                hostname_groups[other_hostname].add(hostname)

    valid_groups = [group for group in hostname_groups.values() if len(group) > 0]

    print(len(valid_groups))
    for group in valid_groups:
        print(' '.join(sorted(group)))

if __name__ == "__main__":
    main()

def is_nice(x, a, b):
    if x % b == 0:
        return False
    k = x // b
    if k % (x % b) == 0:
        return True
    return False

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    a = int(data[0])
    b = int(data[1])

    MOD = 10**9 + 7
    nice_sum = 0

    for x in range(1, a * b + 1):
        if is_nice(x, a, b):
            nice_sum += x
            nice_sum %= MOD

    print(nice_sum)

if __name__ == "__main__":
    main()
